-- Stage1b test candidate only. No production/main deployment authorized.
BEGIN;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolbypassrls)) THEN RAISE EXCEPTION 'cabinet requires BYPASSRLS deployment' USING ERRCODE='42501'; END IF; END $$;
CREATE SCHEMA cabinet_ai;
REVOKE ALL ON SCHEMA cabinet_ai FROM PUBLIC,anon,authenticated;
CREATE TABLE cabinet_ai.flags(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),cabinet_kill boolean NOT NULL DEFAULT true,llm_kill boolean NOT NULL DEFAULT true,retention_seconds int CHECK(retention_seconds BETWEEN 60 AND 2592000),proposal_seconds int CHECK(proposal_seconds BETWEEN 60 AND 86400),user_daily int CHECK(user_daily>0),profile_daily int CHECK(profile_daily>0),global_daily int CHECK(global_daily>0),max_conversations int CHECK(max_conversations BETWEEN 1 AND 100));
INSERT INTO cabinet_ai.flags(singleton) VALUES(true);
CREATE TABLE cabinet_ai.conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,company_id uuid,title text NOT NULL CHECK(length(title)<=120),client_request_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,seq int NOT NULL DEFAULT 0,UNIQUE(owner_id,client_request_id));
CREATE INDEX ON cabinet_ai.conversations(owner_id,created_at);
CREATE INDEX ON cabinet_ai.conversations(expires_at);
CREATE TABLE cabinet_ai.messages(conversation_id uuid REFERENCES cabinet_ai.conversations ON DELETE CASCADE,client_message_id uuid NOT NULL,input_hash text NOT NULL,seq int NOT NULL,user_text text NOT NULL CHECK(length(user_text)<=2000),answer text NOT NULL CHECK(length(answer)<=4000),result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(conversation_id,client_message_id),UNIQUE(conversation_id,seq));
CREATE TABLE cabinet_ai.proposals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES cabinet_ai.conversations ON DELETE CASCADE,owner_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,company_id uuid NOT NULL,message_seq int NOT NULL,ops jsonb NOT NULL CHECK(jsonb_typeof(ops)='array' AND octet_length(ops::text)<=8000),base_fields jsonb NOT NULL,base_hash text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','applied','rejected','superseded','expired')),expires_at timestamptz NOT NULL,resolved_at timestamptz,applied_result jsonb);
CREATE TABLE cabinet_ai.counters(day date NOT NULL,scope text NOT NULL,requests int NOT NULL DEFAULT 0 CHECK(requests>=0),PRIMARY KEY(day,scope));
CREATE TABLE cabinet_ai.audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor uuid,conversation_id uuid,proposal_id uuid,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON ALL TABLES IN SCHEMA cabinet_ai FROM PUBLIC,anon,authenticated;
ALTER TABLE cabinet_ai.flags ENABLE ROW LEVEL SECURITY; ALTER TABLE cabinet_ai.flags FORCE ROW LEVEL SECURITY;
ALTER TABLE cabinet_ai.conversations ENABLE ROW LEVEL SECURITY; ALTER TABLE cabinet_ai.conversations FORCE ROW LEVEL SECURITY;
ALTER TABLE cabinet_ai.messages ENABLE ROW LEVEL SECURITY; ALTER TABLE cabinet_ai.messages FORCE ROW LEVEL SECURITY;
ALTER TABLE cabinet_ai.proposals ENABLE ROW LEVEL SECURITY; ALTER TABLE cabinet_ai.proposals FORCE ROW LEVEL SECURITY;
ALTER TABLE cabinet_ai.counters ENABLE ROW LEVEL SECURITY; ALTER TABLE cabinet_ai.counters FORCE ROW LEVEL SECURITY;
ALTER TABLE cabinet_ai.audit ENABLE ROW LEVEL SECURITY; ALTER TABLE cabinet_ai.audit FORCE ROW LEVEL SECURITY;

CREATE FUNCTION cabinet_ai.can_edit(p_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.company_memberships m JOIN public.companies c ON c.id=m.company_id WHERE m.company_id=p_id AND m.user_id=auth.uid() AND m.verification_status='verified' AND m.role IN ('owner','admin') AND c.status='active') $$;
CREATE FUNCTION cabinet_ai.authenticated() RETURNS void LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF; END $$;
CREATE FUNCTION cabinet_ai.enabled() RETURNS void LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF coalesce((SELECT cabinet_kill OR retention_seconds IS NULL OR proposal_seconds IS NULL OR user_daily IS NULL OR profile_daily IS NULL OR global_daily IS NULL OR max_conversations IS NULL FROM cabinet_ai.flags WHERE singleton),true) THEN RAISE EXCEPTION 'Assistant unavailable' USING ERRCODE='PT503'; END IF; END $$;
CREATE FUNCTION cabinet_ai.allowed(p_conversation uuid) RETURNS cabinet_ai.conversations LANGUAGE plpgsql SET search_path='' AS $$ DECLARE c cabinet_ai.conversations; BEGIN PERFORM cabinet_ai.authenticated(); SELECT * INTO c FROM cabinet_ai.conversations WHERE id=p_conversation AND owner_id=auth.uid() AND expires_at>now(); IF c.id IS NULL OR (c.company_id IS NOT NULL AND NOT cabinet_ai.can_edit(c.company_id)) THEN RAISE EXCEPTION 'Not found' USING ERRCODE='PT404'; END IF; RETURN c; END $$;
CREATE FUNCTION cabinet_ai.clean(p_text text,p_limit int) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$ DECLARE v text; BEGIN IF p_text IS NULL THEN RAISE EXCEPTION 'Invalid value' USING ERRCODE='PT422'; END IF; v:=btrim(regexp_replace(normalize(translate(p_text,U&'\200E\200F\202A\202B\202C\202D\202E\2066\2067\2068\2069',''),NFC),'[[:cntrl:]]',' ','g')); IF length(v)>p_limit OR v ~ '<[^>]*>' THEN RAISE EXCEPTION 'Invalid value' USING ERRCODE='PT422'; END IF; RETURN v; END $$;
CREATE FUNCTION cabinet_ai.validate_ops(p_ops jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$ DECLARE o jsonb; result jsonb:='[]'; fields text[]:='{}'; BEGIN IF jsonb_typeof(p_ops)<>'array' OR jsonb_array_length(p_ops) NOT BETWEEN 1 AND 2 THEN RAISE EXCEPTION 'Invalid operations' USING ERRCODE='PT422'; END IF; FOR o IN SELECT value FROM jsonb_array_elements(p_ops) LOOP IF jsonb_typeof(o)<>'object' OR o-ARRAY['op','field','value']<>'{}' OR o->>'op'<>'set_field' OR coalesce(o->>'field','') NOT IN ('description','city') OR jsonb_typeof(o->'value')<>'string' OR (o->>'field')=ANY(fields) THEN RAISE EXCEPTION 'Invalid operations' USING ERRCODE='PT422'; END IF; fields:=array_append(fields,o->>'field'); result:=result||jsonb_build_array(jsonb_build_object('op','set_field','field',o->>'field','value',cabinet_ai.clean(o->>'value',CASE WHEN o->>'field'='description' THEN 1500 ELSE 120 END))); END LOOP; RETURN result; END $$;
CREATE FUNCTION cabinet_ai.base(p_company uuid,p_ops jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$ SELECT jsonb_object_agg(o->>'field',to_jsonb(c)->(o->>'field')) FROM public.companies c CROSS JOIN jsonb_array_elements(p_ops) o WHERE c.id=p_company $$;
CREATE FUNCTION cabinet_ai.hash(p_value jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT encode(sha256(convert_to(p_value::text,'UTF8')),'hex') $$;
CREATE FUNCTION public.cabinet_get_flags() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN PERFORM cabinet_ai.authenticated(); RETURN coalesce((SELECT jsonb_build_object('cabinet_kill',cabinet_kill,'llm_kill',true,'mode','mock','retention_seconds',retention_seconds) FROM cabinet_ai.flags WHERE singleton),'{"cabinet_kill":true}'::jsonb); END $$;
CREATE FUNCTION public.cabinet_create_conversation(p_company_id uuid,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE c cabinet_ai.conversations; f cabinet_ai.flags; BEGIN PERFORM cabinet_ai.authenticated(); PERFORM cabinet_ai.enabled(); IF p_request_id IS NULL THEN RAISE EXCEPTION 'Request ID required' USING ERRCODE='22023'; END IF; IF p_company_id IS NOT NULL AND NOT cabinet_ai.can_edit(p_company_id) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; SELECT * INTO f FROM cabinet_ai.flags WHERE singleton FOR UPDATE; SELECT * INTO c FROM cabinet_ai.conversations WHERE owner_id=auth.uid() AND client_request_id=p_request_id; IF FOUND THEN IF c.company_id IS DISTINCT FROM p_company_id THEN RAISE EXCEPTION 'Request conflict' USING ERRCODE='PT409'; END IF; PERFORM cabinet_ai.allowed(c.id); RETURN jsonb_build_object('id',c.id); END IF; IF (SELECT count(*) FROM cabinet_ai.conversations WHERE owner_id=auth.uid() AND expires_at>now())>=f.max_conversations THEN RAISE EXCEPTION 'Conversation limit' USING ERRCODE='PT429'; END IF; INSERT INTO cabinet_ai.conversations(owner_id,company_id,title,client_request_id,expires_at) VALUES(auth.uid(),p_company_id,'Новый разговор',p_request_id,now()+make_interval(secs=>f.retention_seconds)) RETURNING * INTO c; RETURN jsonb_build_object('id',c.id); END $$;
CREATE FUNCTION public.cabinet_list_conversations() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN PERFORM cabinet_ai.authenticated(); RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'company_id',c.company_id,'title',c.title,'created_at',c.created_at,'pending_count',(SELECT count(*) FROM cabinet_ai.proposals p WHERE p.conversation_id=c.id AND status='pending' AND p.expires_at>now())) ORDER BY c.created_at DESC) FROM cabinet_ai.conversations c WHERE c.owner_id=auth.uid() AND c.expires_at>now() AND (c.company_id IS NULL OR cabinet_ai.can_edit(c.company_id))),'[]'::jsonb); END $$;
CREATE FUNCTION public.cabinet_get_conversation(p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE c cabinet_ai.conversations; BEGIN c:=cabinet_ai.allowed(p_id); UPDATE cabinet_ai.proposals SET status='expired',resolved_at=now() WHERE conversation_id=c.id AND status='pending' AND expires_at<=now(); RETURN jsonb_build_object('id',c.id,'company_id',c.company_id,'seq',c.seq,'messages',coalesce((SELECT jsonb_agg(jsonb_build_object('seq',m.seq,'user_text',m.user_text,'answer',m.answer) ORDER BY m.seq) FROM cabinet_ai.messages m WHERE m.conversation_id=c.id),'[]'::jsonb),'proposals',coalesce((SELECT jsonb_agg(to_jsonb(p)-'owner_id' ORDER BY message_seq) FROM cabinet_ai.proposals p WHERE p.conversation_id=c.id),'[]'::jsonb)); END $$;
CREATE FUNCTION public.cabinet_delete_conversation(p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN PERFORM cabinet_ai.allowed(p_id); DELETE FROM cabinet_ai.conversations WHERE id=p_id; RETURN '{"deleted":true}'::jsonb; END $$;
CREATE FUNCTION public.cabinet_profile_context(p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN PERFORM cabinet_ai.authenticated(); IF NOT cabinet_ai.can_edit(p_id) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; RETURN (SELECT jsonb_build_object('name',name,'description',description,'city',city) FROM public.companies WHERE id=p_id); END $$;
CREATE FUNCTION public.cabinet_send_mock(p_conversation uuid,p_message_id uuid,p_text text,p_expected_seq int,p_hint text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE c cabinet_ai.conversations; f cabinet_ai.flags; m cabinet_ai.messages; v_hash text; v_answer text; v_value text; v_field text; v_ops jsonb; v_base jsonb; v_proposal uuid; v_result jsonb; scope_key text; cap int; BEGIN PERFORM cabinet_ai.enabled(); c:=cabinet_ai.allowed(p_conversation); IF p_text IS NULL OR length(p_text) NOT BETWEEN 1 AND 2000 OR p_hint IS NULL OR length(p_hint)>4000 OR p_message_id IS NULL THEN RAISE EXCEPTION 'Invalid message' USING ERRCODE='22023'; END IF; IF NOT pg_try_advisory_xact_lock(hashtextextended('otzovik:cabinet:conversation:'||c.id,0)) THEN RAISE EXCEPTION 'Busy' USING ERRCODE='PT409'; END IF; v_hash:=cabinet_ai.hash(jsonb_build_array(p_text,p_hint)); SELECT * INTO m FROM cabinet_ai.messages WHERE conversation_id=c.id AND client_message_id=p_message_id; IF FOUND THEN IF m.input_hash<>v_hash THEN RAISE EXCEPTION 'Request conflict' USING ERRCODE='PT409'; END IF; RETURN m.result; END IF; SELECT * INTO c FROM cabinet_ai.conversations WHERE id=c.id FOR UPDATE; IF p_expected_seq IS DISTINCT FROM c.seq THEN RAISE EXCEPTION 'Conversation changed' USING ERRCODE='PT409'; END IF; SELECT * INTO f FROM cabinet_ai.flags WHERE singleton FOR UPDATE; PERFORM cabinet_ai.enabled();
 FOREACH scope_key IN ARRAY ARRAY['user:'||auth.uid(),'profile:'||coalesce(c.company_id::text,'general:'||auth.uid()),'global'] LOOP cap:=CASE WHEN scope_key LIKE 'user:%' THEN f.user_daily WHEN scope_key='global' THEN f.global_daily ELSE f.profile_daily END; INSERT INTO cabinet_ai.counters(day,scope) VALUES(current_date,scope_key) ON CONFLICT DO NOTHING; IF (SELECT requests FROM cabinet_ai.counters WHERE day=current_date AND scope=scope_key)>=cap THEN RAISE EXCEPTION 'Quota exceeded' USING ERRCODE='PT429'; END IF; UPDATE cabinet_ai.counters SET requests=requests+1 WHERE day=current_date AND scope=scope_key; END LOOP;
 v_answer:='Помощь: профиль создаётся в «Мои компании». Описание и город меняются в разделе «Профиль». Поиск и AI-провайдер в этом тесте отключены.';
 IF c.company_id IS NOT NULL AND (p_text LIKE 'Описание:%' OR p_text LIKE 'Город:%') THEN v_field:=CASE WHEN p_text LIKE 'Описание:%' THEN 'description' ELSE 'city' END; v_value:=btrim(substr(p_text,strpos(p_text,':')+1)); v_ops:=cabinet_ai.validate_ops(jsonb_build_array(jsonb_build_object('op','set_field','field',v_field,'value',v_value))); v_base:=cabinet_ai.base(c.company_id,v_ops); INSERT INTO cabinet_ai.proposals(conversation_id,owner_id,company_id,message_seq,ops,base_fields,base_hash,expires_at) VALUES(c.id,auth.uid(),c.company_id,c.seq+1,v_ops,v_base,cabinet_ai.hash(v_base),least(c.expires_at,now()+make_interval(secs=>f.proposal_seconds))) RETURNING id INTO v_proposal; v_answer:='Предложение сохранено. Проверьте «Было → станет» и подтвердите отдельно. Профиль ещё не изменён.'; END IF;
 v_result:=jsonb_build_object('answer',v_answer,'seq',c.seq+1,'proposal_id',v_proposal,'mode','mock'); INSERT INTO cabinet_ai.messages VALUES(c.id,p_message_id,v_hash,c.seq+1,p_text,v_answer,v_result,now()); UPDATE cabinet_ai.conversations SET seq=seq+1,title=left(p_text,120) WHERE id=c.id; RETURN v_result;
END $$;
CREATE FUNCTION public.cabinet_reject_proposal(p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE p cabinet_ai.proposals; BEGIN SELECT * INTO p FROM cabinet_ai.proposals WHERE id=p_id AND owner_id=auth.uid() FOR UPDATE; IF p.id IS NULL THEN RAISE EXCEPTION 'Not found' USING ERRCODE='PT404'; END IF; PERFORM cabinet_ai.allowed(p.conversation_id); IF p.status<>'pending' THEN RAISE EXCEPTION 'Proposal completed' USING ERRCODE='PT409'; END IF; UPDATE cabinet_ai.proposals SET status='rejected',resolved_at=now() WHERE id=p.id; RETURN '{"rejected":true}'::jsonb; END $$;
CREATE FUNCTION public.cabinet_apply_proposal(p_id uuid,p_expected_hash text,p_confirmed boolean,p_edits jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE p cabinet_ai.proposals; c public.companies; v_ops jsonb; fields jsonb; result jsonb; ignored jsonb; BEGIN PERFORM cabinet_ai.enabled(); SELECT * INTO p FROM cabinet_ai.proposals WHERE id=p_id AND owner_id=auth.uid(); IF p.id IS NULL THEN RAISE EXCEPTION 'Not found' USING ERRCODE='PT404'; END IF; PERFORM cabinet_ai.allowed(p.conversation_id); IF p_confirmed IS DISTINCT FROM true THEN RAISE EXCEPTION 'Explicit confirmation required' USING ERRCODE='22023'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('otzovik:cabinet:profile:company:'||p.company_id,0)); SELECT * INTO p FROM cabinet_ai.proposals WHERE id=p_id FOR UPDATE; IF p.status='applied' THEN RETURN p.applied_result; END IF; IF p.status<>'pending' THEN RAISE EXCEPTION 'Proposal completed' USING ERRCODE='PT409'; END IF; IF p.expires_at<=now() THEN UPDATE cabinet_ai.proposals SET status='expired',resolved_at=now() WHERE id=p.id; PERFORM set_config('response.status','409',true); RETURN '{"status":"expired"}'::jsonb; END IF; IF p_expected_hash IS DISTINCT FROM p.base_hash THEN RAISE EXCEPTION 'Invalid base hash' USING ERRCODE='PT409'; END IF;
 SELECT * INTO c FROM public.companies WHERE id=p.company_id FOR UPDATE; IF NOT cabinet_ai.can_edit(p.company_id) THEN RAISE EXCEPTION 'Not found' USING ERRCODE='PT404'; END IF; IF cabinet_ai.hash(cabinet_ai.base(c.id,p.ops))<>p.base_hash THEN UPDATE cabinet_ai.proposals SET status='superseded',resolved_at=now() WHERE id=p.id; PERFORM set_config('response.status','409',true); RETURN '{"status":"superseded"}'::jsonb; END IF;
 v_ops:=cabinet_ai.validate_ops(coalesce(p_edits,p.ops)); IF (SELECT array_agg(value->>'field' ORDER BY value->>'field') FROM jsonb_array_elements(v_ops)) IS DISTINCT FROM (SELECT array_agg(value->>'field' ORDER BY value->>'field') FROM jsonb_array_elements(p.ops)) THEN RAISE EXCEPTION 'Fields cannot change' USING ERRCODE='PT422'; END IF; SELECT jsonb_object_agg(o->>'field',o->>'value') INTO fields FROM jsonb_array_elements(v_ops) o;
 -- Existing validator/rights/audit are reused under the SAME locked row and transaction.
 ignored:=public.update_my_company_profile(c.id,c.name,CASE WHEN fields?'description' THEN fields->>'description' ELSE c.description END,c.website,c.phone,CASE WHEN fields?'city' THEN fields->>'city' ELSE c.city END,c.email);
 PERFORM cabinet_ai.enabled(); result:=jsonb_build_object('status','applied','proposal_id',p.id,'company_id',c.id); UPDATE cabinet_ai.proposals SET status='applied',ops=v_ops,applied_result=result,resolved_at=now() WHERE id=p.id; INSERT INTO cabinet_ai.audit(actor,conversation_id,proposal_id,action) VALUES(auth.uid(),p.conversation_id,p.id,'apply_draft'); RETURN result;
END $$;
CREATE FUNCTION cabinet_ai.sweep() RETURNS void LANGUAGE plpgsql SET search_path='' AS $$ BEGIN DELETE FROM cabinet_ai.conversations c WHERE c.expires_at<=now() OR (c.company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.companies p WHERE p.id=c.company_id)); UPDATE cabinet_ai.proposals SET status='expired',resolved_at=now() WHERE status='pending' AND expires_at<=now(); END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA cabinet_ai FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.cabinet_get_flags() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cabinet_get_flags() TO authenticated;
REVOKE ALL ON FUNCTION public.cabinet_create_conversation(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cabinet_create_conversation(uuid,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.cabinet_list_conversations() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cabinet_list_conversations() TO authenticated;
REVOKE ALL ON FUNCTION public.cabinet_get_conversation(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cabinet_get_conversation(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.cabinet_delete_conversation(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cabinet_delete_conversation(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.cabinet_profile_context(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cabinet_profile_context(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.cabinet_send_mock(uuid,uuid,text,integer,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cabinet_send_mock(uuid,uuid,text,integer,text) TO authenticated;
REVOKE ALL ON FUNCTION public.cabinet_reject_proposal(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cabinet_reject_proposal(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.cabinet_apply_proposal(uuid,text,boolean,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cabinet_apply_proposal(uuid,text,boolean,jsonb) TO authenticated;
COMMIT;
